// ##################

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import ImageWithFallback from "@/components/image-with-fallback";
import { Separator } from "@/components/ui/separator";
import { globalErrorToast, globalSuccessToast } from "@/lib/toast";
import { pageHead } from "@/utils/page-head";
import { queryClient, trpc } from "@/utils/trpc";
import { useMutation, useSuspenseQuery } from "@tanstack/react-query";
import { createFileRoute, Link, redirect } from "@tanstack/react-router";
import {
  ArrowLeft,
  BookOpen,
  CheckCircle2,
  Clock,
  Upload,
  XCircle,
  AlertCircle,
} from "lucide-react";
import { useRef, useState } from "react";

import { authMeQueryOptions } from "@/utils/auth-query";

export const Route = createFileRoute("/pelatihan/transaksi/$orderId")({
  beforeLoad: async ({ context, params }) => {
    try {
      const user =
        await context.queryClient.ensureQueryData(authMeQueryOptions());
      if (!user) {
        throw redirect({
          to: "/login",
          search: { redirect: `/pelatihan/transaksi/${params.orderId}` },
        });
      }
    } catch (error) {
      if (error && typeof error === "object" && "isRedirect" in error) {
        throw error;
      }
      throw redirect({ to: "/login" });
    }
  },
  head: () => pageHead("Detail Transaksi Pelatihan"),
  component: RouteComponent,
});

const ORDER_STATUS_CONFIG: Record<
  string,
  {
    label: string;
    variant: "default" | "secondary" | "destructive" | "outline";
    icon: React.ComponentType<{ className?: string }>;
  }
> = {
  pending: { label: "Menunggu Pembayaran", variant: "secondary", icon: Clock },
  waiting_payment: {
    label: "Menunggu Pembayaran",
    variant: "secondary",
    icon: Clock,
  },
  waiting_verification: {
    label: "Menunggu Verifikasi",
    variant: "outline",
    icon: Clock,
  },
  verified: {
    label: "Pembayaran Terverifikasi",
    variant: "default",
    icon: CheckCircle2,
  },
  cancelled: { label: "Dibatalkan", variant: "destructive", icon: XCircle },
  expired: { label: "Kadaluarsa", variant: "destructive", icon: XCircle },
  rejected: { label: "Ditolak", variant: "destructive", icon: XCircle },
};

function RouteComponent() {
  const { orderId } = Route.useParams();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  const { data: order } = useSuspenseQuery(
    trpc.pelatihan.order.getUserOrderById.queryOptions({ id: orderId }),
  );

  const uploadMutation = useMutation(
    trpc.pelatihan.order.uploadPaymentProof.mutationOptions({
      onSuccess: async () => {
        await queryClient.invalidateQueries(
          trpc.pelatihan.order.getUserOrderById.queryOptions({ id: orderId }),
        );
        await queryClient.invalidateQueries(
          trpc.pelatihan.order.getUserOrders.queryOptions(),
        );
        globalSuccessToast(
          "Bukti pembayaran berhasil diunggah. Admin akan segera memverifikasi.",
        );
        setPreviewUrl(null);
        setSelectedFile(null);
      },
      onError: (err) => {
        globalErrorToast(`Gagal mengunggah: ${err.message}`);
      },
    }),
  );

  let statusConfig: {
    label: string;
    variant: "default" | "secondary" | "destructive" | "outline";
    icon: React.ComponentType<{ className?: string }>;
  };

  if (order.approvalStatus === "pending") {
    statusConfig = {
      label: "Menunggu Persetujuan Admin",
      variant: "secondary",
      icon: Clock,
    };
  } else if (order.approvalStatus === "rejected") {
    statusConfig = {
      label: "Order Ditolak",
      variant: "destructive",
      icon: XCircle,
    };
  } else if (order.paymentStatus === "rejected") {
    statusConfig = {
      label: "Pembayaran Ditolak",
      variant: "destructive",
      icon: XCircle,
    };
  } else {
    statusConfig = (ORDER_STATUS_CONFIG[order.status] ??
      ORDER_STATUS_CONFIG.pending) as {
      label: string;
      variant: "default" | "secondary" | "destructive" | "outline";
      icon: React.ComponentType<{ className?: string }>;
    };
  }

  const StatusIcon = statusConfig.icon;

  const canUploadProof =
    order.approvalStatus === "approved" &&
    (order.status === "waiting_payment" ||
      order.status === "waiting_verification" ||
      order.paymentStatus === "rejected");

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith("image/") && file.type !== "application/pdf") {
      globalErrorToast("File harus berupa gambar (JPG/PNG) atau PDF");
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      globalErrorToast("Ukuran file maksimal 5MB");
      return;
    }

    setSelectedFile(file);
    const url = URL.createObjectURL(file);
    setPreviewUrl(url);
  };

  const handleSubmitProof = () => {
    if (!selectedFile) return;
    const formData = new FormData();
    formData.append("orderId", orderId);
    formData.append("file", selectedFile);
    uploadMutation.mutate(formData);
  };

  return (
    <div className="mx-auto max-w-2xl px-4 py-8 sm:px-0">
      {/* Back button */}
      <Link
        to="/pelatihan/transaksi"
        className="mb-6 flex w-fit items-center gap-2 text-sm text-muted-foreground transition-colors hover:text-foreground"
      >
        <ArrowLeft className="h-4 w-4" />
        Kembali ke Riwayat Transaksi
      </Link>

      {/* Order Status Header */}
      <div className="mb-6 rounded-xl border bg-gradient-to-br from-primary/5 to-primary/10 p-6">
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className="text-sm text-muted-foreground">Nomor Transaksi</p>
            <h1 className="mt-1 text-xl font-bold">{order.orderNumber}</h1>
            <p className="mt-1 text-sm text-muted-foreground">
              {new Date(order.createdAt).toLocaleDateString("id-ID", {
                weekday: "long",
                day: "numeric",
                month: "long",
                year: "numeric",
                hour: "2-digit",
                minute: "2-digit",
              })}
            </p>
          </div>
          <Badge
            variant={statusConfig.variant}
            className="flex items-center gap-1.5 px-3 py-1.5 text-sm"
          >
            <StatusIcon className="h-3.5 w-3.5" />
            {statusConfig.label}
          </Badge>
        </div>
      </div>

      {/* Items */}
      <Card className="mb-4">
        <CardHeader className="pb-3">
          <CardTitle className="text-base">
            Kelas yang Dibeli ({order.items.length})
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <div className="divide-y">
            {order.items.map((item) => (
              <div key={item.id} className="flex items-center gap-4 p-4">
                <div className="h-16 w-24 flex-shrink-0 overflow-hidden rounded-lg bg-muted">
                  {item.pelatihan.thumbnailUrl ? (
                    <ImageWithFallback
                      src={item.pelatihan.thumbnailUrl}
                      alt={item.pelatihan.title}
                      className="h-full w-full object-cover"
                    />
                  ) : (
                    <div className="flex h-full w-full items-center justify-center">
                      <BookOpen className="h-6 w-6 text-muted-foreground/40" />
                    </div>
                  )}
                </div>
                <div className="min-w-0 flex-1">
                  <Link
                    to="/pelatihan/$slug"
                    params={{ slug: item.pelatihan.slug }}
                    className="line-clamp-2 font-medium hover:text-primary hover:underline"
                  >
                    {item.pelatihan.title}
                  </Link>
                </div>
                <div className="flex-shrink-0 text-right">
                  <p className="font-semibold">
                    {item.price === 0
                      ? "Gratis"
                      : `Rp ${item.price.toLocaleString("id-ID")}`}
                  </p>
                </div>
              </div>
            ))}
          </div>

          <Separator />
          <div className="flex items-center justify-between p-4">
            <span className="font-medium text-muted-foreground">
              Total Pembayaran
            </span>
            <span className="text-xl font-bold">
              Rp {order.totalAmount.toLocaleString("id-ID")}
            </span>
          </div>
        </CardContent>
      </Card>

      {/* Approval Status Alert/Card */}
      {order.approvalStatus === "pending" && (
        <Card className="mb-4">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <Clock className="h-5 w-5 animate-pulse text-amber-500" />
              Menunggu Persetujuan Admin
            </CardTitle>
            <CardDescription>
              Pesanan Anda sedang ditinjau oleh Admin Pelatihan. Harap menunggu
              hingga pesanan disetujui sebelum melakukan pembayaran.
            </CardDescription>
          </CardHeader>
        </Card>
      )}

      {order.approvalStatus === "rejected" && (
        <Card className="mb-4 border-destructive/50 bg-destructive/5">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base text-destructive">
              <XCircle className="h-5 w-5" />
              Pesanan Ditolak
            </CardTitle>
            <CardDescription className="text-destructive/80">
              Pesanan Anda telah ditolak oleh Admin Pelatihan.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="rounded-lg border bg-background p-4">
              <p className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">
                Alasan Penolakan:
              </p>
              <p className="mt-1 text-sm font-medium text-foreground">
                {order.approvalRejectReason ||
                  "Tidak ada alasan yang diberikan."}
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Payment Proof Upload — only if can still upload */}
      {canUploadProof && (
        <Card className="mb-4">
          <CardHeader>
            <CardTitle className="text-base">Upload Bukti Pembayaran</CardTitle>
            <CardDescription>
              Silakan transfer ke rekening berikut, kemudian upload bukti
              pembayaran.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Rejection alert if payment proof was previously rejected */}
            {order.paymentStatus === "rejected" && (
              <Alert variant="destructive" className="mb-2">
                <AlertCircle className="h-4 w-4" />
                <AlertTitle>Pembayaran Ditolak</AlertTitle>
                <AlertDescription>
                  Bukti pembayaran Anda ditolak oleh Admin Pelatihan dengan
                  alasan:{" "}
                  <strong>
                    {order.paymentRejectedReason ||
                      "Tidak ada alasan yang diberikan."}
                  </strong>
                  . Silakan unggah kembali bukti transfer yang valid.
                </AlertDescription>
              </Alert>
            )}
            {/* Bank Info */}
            <div className="space-y-2 rounded-lg bg-muted/50 p-4">
              <p className="text-sm font-semibold text-foreground">
                Rekening Tujuan
              </p>
              <div className="space-y-1 text-sm">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Bank</span>
                  <span className="font-medium">BRI</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">No. Rekening</span>
                  <span className="font-mono font-medium">
                    1234-5678-9012-3456
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Atas Nama</span>
                  <span className="font-medium">Tepian K3 Laboratory</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Jumlah</span>
                  <span className="font-bold text-primary">
                    Rp {order.totalAmount.toLocaleString("id-ID")}
                  </span>
                </div>
              </div>
            </div>

            {/* Already uploaded */}
            {order.paymentProofUrl && (
              <div className="rounded-lg border border-amber-200 bg-amber-50 p-3">
                <p className="text-sm font-medium text-amber-800">
                  Bukti pembayaran sudah diunggah dan sedang dalam proses
                  verifikasi.
                </p>
                {order.paymentProofUploadedAt && (
                  <p className="mt-1 text-xs text-amber-700">
                    Diunggah:{" "}
                    {new Date(order.paymentProofUploadedAt).toLocaleDateString(
                      "id-ID",
                      {
                        day: "numeric",
                        month: "long",
                        year: "numeric",
                        hour: "2-digit",
                        minute: "2-digit",
                      },
                    )}
                  </p>
                )}
              </div>
            )}

            {/* File upload */}
            <div>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*,application/pdf"
                className="hidden"
                onChange={handleFileChange}
              />

              {previewUrl ? (
                <div className="space-y-3">
                  <ImageWithFallback
                    src={previewUrl}
                    alt="Preview bukti bayar"
                    className="max-h-48 w-full rounded-lg border bg-muted object-contain"
                  />
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      className="flex-1"
                      onClick={() => {
                        setPreviewUrl(null);
                        setSelectedFile(null);
                        if (fileInputRef.current)
                          fileInputRef.current.value = "";
                      }}
                    >
                      Ganti File
                    </Button>
                    <Button
                      className="flex-1"
                      onClick={handleSubmitProof}
                      disabled={uploadMutation.isPending || !selectedFile}
                    >
                      {uploadMutation.isPending
                        ? "Mengunggah..."
                        : "Kirim Bukti Bayar"}
                    </Button>
                  </div>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="group flex w-full flex-col items-center gap-3 rounded-lg border-2 border-dashed border-muted-foreground/30 p-8 text-muted-foreground transition-colors hover:border-primary/50 hover:text-primary"
                >
                  <div className="rounded-full bg-muted p-3 transition-colors group-hover:bg-primary/10">
                    <Upload className="h-6 w-6" />
                  </div>
                  <div className="text-center">
                    <p className="text-sm font-medium">
                      Klik untuk memilih file
                    </p>
                    <p className="mt-1 text-xs">
                      JPG, PNG, atau PDF • Maks 5MB
                    </p>
                  </div>
                </button>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Verified state */}
      {order.status === "verified" && (
        <Card className="border-green-200 bg-green-50">
          <CardContent className="pt-6">
            <div className="flex items-start gap-3">
              <CheckCircle2 className="mt-0.5 h-5 w-5 flex-shrink-0 text-green-600" />
              <div>
                <p className="font-semibold text-green-800">
                  Pembayaran Terverifikasi!
                </p>
                <p className="mt-1 text-sm text-green-700">
                  Anda sudah terdaftar di semua kelas yang dibeli. Silakan
                  kunjungi halaman Pelatihan Saya untuk mulai belajar.
                </p>
                {order.verifiedAt && (
                  <p className="mt-2 text-xs text-green-600">
                    Diverifikasi:{" "}
                    {new Date(order.verifiedAt).toLocaleDateString("id-ID", {
                      day: "numeric",
                      month: "long",
                      year: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </p>
                )}
                <Button asChild className="mt-3" size="sm">
                  <Link to="/dashboard/pelatihan">Lihat Pelatihan Saya</Link>
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

